library(readr); library(dplyr); wave1 <- read_delim('data/input/wave_one_lsype_young_person_2020.tab', delim = '\t'); wave4 <- read_delim('data/input/wave_four_lsype_young_person_2020.tab', delim = '\t'); ns8_main <- read_delim('data/input/ns8_2015_main_interview.tab', delim = '\t'); ns8_derived <- read_delim('data/input/ns8_2015_derived.tab', delim = '\t'); ns9_main <- read_delim('data/input/ns9_2022_main_interview.tab', delim = '\t'); ns9_derived <- read_delim('data/input/ns9_2022_derived_variables.tab', delim = '\t'); merged <- wave1 %>% full_join(wave4, by = 'NSID') %>% full_join(ns8_main, by = 'NSID') %>% full_join(ns8_derived, by = 'NSID') %>% full_join(ns9_main, by = 'NSID') %>% full_join(ns9_derived, by = 'NSID'); merged$educ25 <- NA; merged$educ32 <- NA; write_csv(merged %>% select(NSID, educ25, educ32), 'data/output/cleaned_data.csv')